import random, math
from app.api.handlers import handle_calc

def gen(depth=0):
    r = random.random()
    if depth > 3 or r < 0.35:
        return str(random.randint(0, 9))
    if r < 0.5:
        return '-' + gen(depth+1)
    if r < 0.6:
        return '(' + gen(depth+1) + ')'
    op = random.choice('+-*/')
    return gen(depth+1) + random.choice(['',' ']) + op + random.choice(['',' ']) + gen(depth+1)

random.seed(0)
bad = 0
for _ in range(20000):
    e = gen()
    if len(e) > 100: continue
    try:
        ref = eval(e)  # scratch reference only
    except ZeroDivisionError:
        exp = (400, {'error': 'division by zero'})
    except Exception:
        continue
    got = handle_calc({'expr': e})
    if isinstance(ref, float) and ref.is_integer():
        ref = int(ref)
    if ref == int(ref):
        ref = int(ref)
    exp = (200, {'result': ref})
    if got != exp:
        bad += 1
        if bad < 10:
            print('MISMATCH', repr(e), got, exp)
print('mismatches:', bad)
"

